// Leaks: no cancel path, uncaught exceptions crash
GlobalScope.launch {
    while (isActive) { poll() }   // survives the screen forever
}

// Owned by the app, cancelled with it:
class AppScope(application: Application) {
    val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
}

// Must survive process death:
WorkManager.enqueue(UploadWork())

class SaveRepository(
    @ApplicationScope private val appScope: CoroutineScope,
    private val api: Api
) {
    fun save(draft: Draft) {
        appScope.launch {
            api.post(draft)   // survives the ViewModel being cleared
        }
    }
}

// Or, when it must survive process death:
WorkManager.getInstance(context).enqueueUniqueWork(
    "save-" + draft.id, ExistingWorkPolicy.REPLACE, SaveWorker(...))

val handler = CoroutineExceptionHandler { _, t ->
    log("caught: ${t.message}")
}

// Fires: the handler is on the scope's root context
val scope = CoroutineScope(SupervisorJob() + handler)
scope.launch { throw RuntimeException("boom") }

// Ignored: installed on a child, exception goes to the parent
scope.launch(handler) { throw RuntimeException("also boom") }

// Never fires for async: the error sits in the Deferred
val d = scope.async { throw RuntimeException("async boom") }
// ... until await() throws it

suspend fun loadAll(): Triple<Profile, Settings, Feed> =
    coroutineScope {
        val p = async { repo.profile() }
        val s = async { repo.settings() }
        val f = async { repo.feed() }
        Triple(p.await(), s.await(), f.await())  // fail-fast: any throw cancels all
    }

suspend fun loadBestEffort(): Loaded =
    supervisorScope {
        val p = async { runCatching { repo.profile() } }
        val s = async { runCatching { repo.settings() } }
        val f = async { runCatching { repo.feed() } }
        Loaded(p.await().getOrNull(), s.await().getOrNull(), f.await().getOrNull())
    }

// select: you must cancel the loser yourself
coroutineScope {
    val cache = async { cache.read() }
    val net = async { api.fetch() }
    val winner = select<Data> {
        cache.onAwait { it }
        net.onAwait { it }
    }
    if (!cache.isCompleted) cache.cancel()
    if (!net.isCompleted) net.cancel()
    winner
}

// Simpler, automatic teardown:
withTimeoutOrNull(2_000) { api.fetch() } ?: cache.read()
// or
merge(cacheFlow(), networkFlow()).first()

// Not cancellable: no suspension point anywhere
launch {
    while (true) { crunch() }
}

// Cancellable: throws on cancellation
launch {
    while (true) {
        ensureActive()
        crunch()
    }
}

// Clean exit + join so the test waits for it
val job = scope.launch { while (isActive) { work() } }
job.cancel()
job.join()      // actually finished

try {
    api.load()
} catch (e: Exception) {
    if (e is CancellationException) throw e   // never swallow the signal
    showError(e)
}

// runCatching is the same trap — it catches Throwable:
val result = runCatching { api.load() }   // cancellation eaten

suspend fun upload() {
    val stream = openStream()
    try {
        stream.write(data)          // can be cancelled
    } finally {
        withContext(NonCancellable) {
            stream.close()          // suspending cleanup MUST complete
        }
    }
}

// Non-suspending cleanup needs no NonCancellable:
fun read() = file.inputStream().use { it.readBytes() }

// Throws TimeoutCancellationException
val a = withTimeout(1_000) { slowApi() }

// Returns null instead
val b = withTimeoutOrNull(1_000) { slowApi() } ?: fallback()

// WRONG: swallowing the signal
val c = try { withTimeout(1_000) { slowApi() } }
       catch (e: Exception) { fallback() }      // eats cancellation

// RIGHT:
val c2 = try { withTimeout(1_000) { slowApi() } }
        catch (e: TimeoutCancellationException) { fallback() }
        catch (e: CancellationException) { throw e }

suspend fun download(url: String): Response =
    suspendCancellableCoroutine { cont ->
        val call = client.newCall(Request(url))
        call.enqueue { resp ->
            // If the continuation is already cancelled,
            // the lambda receives the value and closes it:
            cont.resume(resp) { r -> r.close() }
        }
        cont.invokeOnCancellation { call.cancel() }
    }

// Channel equivalent:
val results = Channel<Response>(onUndeliveredElement = { it.close() })
